const ExcelJS = require('exceljs');
async function run() {
  const stream = new ExcelJS.stream.xlsx.WorkbookReader('data/(데이터검증팀)실사 DB 취합_전달용_260720_배현명.xlsx', {});
  const rowNumbers = [];
  for await (const ws of stream) {
    if (ws.name !== '기업 정보') continue;
    for await (const row of ws) {
      if (row.values[1] === '배현명') {
        rowNumbers.push(row.number);
      }
    }
  }
  console.log('Total 배현명 rows:', rowNumbers.length);
  console.log('Min:', rowNumbers[0], 'Max:', rowNumbers[rowNumbers.length - 1]);
  // check gaps
  let gaps = [];
  for (let i = 1; i < rowNumbers.length; i++) {
    if (rowNumbers[i] - rowNumbers[i-1] > 1) {
      gaps.push([rowNumbers[i-1], rowNumbers[i]]);
    }
  }
  console.log('Gaps:', gaps);
}
run();
